DROP TABLE IF EXISTS `orders`;
CREATE TABLE `orders` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `customer_id` int(11) NOT NULL,
  `total` decimal(10,2) NOT NULL DEFAULT 0.00,
  `original_total` decimal(10,2) NOT NULL DEFAULT 0.00,
  `complimentary_total` decimal(10,2) NOT NULL DEFAULT 0.00,
  `order_type` enum('paid','complimentary','mixed') NOT NULL DEFAULT 'paid',
  `status` enum('Pending','Preparing','Delivered','Cancelled','Reversed') NOT NULL DEFAULT 'Pending',
  `cancel_reason` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_orders_customer` (`customer_id`,`created_at`),
  KEY `idx_orders_status` (`status`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

