DROP TABLE IF EXISTS `purchases`;
CREATE TABLE `purchases` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kitchen_id` int(11) NOT NULL,
  `purchase_date` date NOT NULL,
  `purchase_item_id` int(11) DEFAULT NULL,
  `category` varchar(100) DEFAULT NULL,
  `item_name` varchar(100) NOT NULL,
  `quantity` decimal(10,2) NOT NULL,
  `unit` varchar(20) NOT NULL DEFAULT 'KG',
  `vendor` varchar(100) DEFAULT NULL,
  `vendor_id` int(11) DEFAULT NULL,
  `vendor_name` varchar(100) DEFAULT NULL,
  `rate` decimal(10,2) NOT NULL,
  `total_amount` decimal(10,2) NOT NULL,
  `bill_number` varchar(50) DEFAULT NULL,
  `bill_image` varchar(255) DEFAULT NULL,
  `payment_type` enum('Cash','Bank','Credit') NOT NULL DEFAULT 'Cash',
  `remarks` varchar(255) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_purchases_kitchen_date` (`kitchen_id`,`purchase_date`),
  KEY `idx_purchases_vendor` (`vendor_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

INSERT INTO `purchases` (`id`, `kitchen_id`, `purchase_date`, `purchase_item_id`, `category`, `item_name`, `quantity`, `unit`, `vendor`, `vendor_id`, `vendor_name`, `rate`, `total_amount`, `bill_number`, `bill_image`, `payment_type`, `remarks`, `created_by`, `created_at`) VALUES
(1,	1,	'2026-07-21',	1,	NULL,	'Basmati Rice',	10.00,	'KG',	'City Supplier',	1,	'City Supplier',	350.00,	3500.00,	'',	NULL,	'Cash',	'',	2,	'2026-07-21 13:14:05');

DROP TABLE IF EXISTS `purchase_items`;
CREATE TABLE `purchase_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `unit` varchar(20) NOT NULL DEFAULT 'KG',
  `status` enum('active','inactive') NOT NULL DEFAULT 'active',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_purchase_item_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

